import{residualCylinder}from './optics.js';import{sources,evidence}from './evidence.js';
const $=id=>document.getElementById(id);const base={aspheric:true,toric:false,glasses:false,astig:.75,rotation:0,pupil:4,decenter:0,distance:0};let configs={a:{...base,glasses:true},b:{...base,toric:true}},scene='psf',example='cylinder',edit='b',view='split',lens='mono',serial=0;const latest={a:0,b:0},results={},pending=new Map();let busy=false,queue=[],timer,loaded=false;const worker=new Worker('worker.js',{type:'module'}),road=new Image();road.src='pj-night.png';road.onload=()=>{loaded=true;if(scene==='road')renderBoth();};road.onerror=()=>{$('status').textContent='夜景暂不可用，请选择点光源。';};const buffer=document.createElement('canvas');buffer.width=640;buffer.height=360;const c=buffer.getContext('2d',{willReadFrequently:true});
function setView(v){view=v;document.querySelector('.lab').dataset.view=v;document.querySelectorAll('[data-view]').forEach(e=>e.setAttribute('aria-pressed',String(e.dataset.view===v)));}
function sync(){const s=configs[edit];$('settings-target').textContent=edit.toUpperCase();$('science-target').textContent=edit.toUpperCase();for(const key of ['aspheric','toric','glasses'])$(key).checked=s[key];for(const key of ['astig','rotation','pupil','decenter'])$(key).value=s[key];$('astig-value').textContent=s.astig.toFixed(2)+' D';$('rotation-value').textContent=s.rotation+'°';$('pupil-value').textContent=s.pupil.toFixed(1)+' mm';$('decenter-value').textContent=s.decenter.toFixed(2)+' mm';$('rotation').disabled=!s.toric;$('decenter').disabled=!s.aspheric;$('rotation-note').textContent=!s.toric?'Toric（散光型）矫正已关闭。':s.glasses?'在理想模型中，眼镜抵消残余散光。':'旋转会留下残余散光；此数值不是发生概率。';$('residual').textContent=residualCylinder(s).toFixed(2)+' D';$('copy').textContent=edit==='b'?'将 A 设置复制到 B':'将 B 设置复制到 A';$('scene').value=scene;$('scene').disabled=example==='near';$('example').value=example;$('distance-control').hidden=example==='near'||scene!=='reading';$('distance').value=configs.b.distance||2.5;document.querySelectorAll('[data-edit]').forEach(e=>e.setAttribute('aria-pressed',String(e.dataset.edit===edit)));for(const t of ['a','b']){const q=configs[t];$('name-'+t).textContent=example==='near'?(q.distance===0?'远处目标':'近处 · 未戴阅读眼镜'):example==='aspheric'?(q.aspheric?'理想 Aspheric（非球面）补偿':'补偿关闭'):(q.glasses?'理想散光眼镜':q.astig===0?'本例无散光':residualCylinder(q)<.01?'Toric（散光型）轴位对准':q.toric?'轴位旋转':'未作矫正');$('summary-'+t).textContent=example==='near'?'相同单焦点光学 · 无阅读附加度数':example==='aspheric'?'示例瞳孔 '+q.pupil.toFixed(1)+' mm':'示例散光 '+q.astig.toFixed(2)+' D · 残余 '+residualCylinder(q).toFixed(2)+' D';}$('scene-caption').textContent=scene==='psf'?'计算 PSF · 放大、对数光强':scene==='road'?'PJ 生成街景＋计算模糊 · 保留原图成像痕迹':'合成文字＋计算模糊 · 并非视力表';if(results[edit])graphs(results[edit]);}
function makeScene(){c.fillStyle='#020509';c.fillRect(0,0,640,360);if(scene==='road'&&loaded)c.drawImage(road,0,0,640,360);else if(scene==='reading'){c.fillStyle='#d6d9d5';c.fillRect(0,0,640,360);c.fillStyle='#222';c.font='26px Georgia';c.fillText('在选定距离看清。',32,53);c.font='22px Georgia';c.fillText('眼镜可补足所需焦点。',32,99);for(let j=0;j<4;j++){const co=[.85,.35,.12,.04][j],g=Math.round(214*(1-co));c.fillStyle=`rgb(${g},${g},${g})`;c.font='23px sans-serif';c.fillText('C E F P T',32+j*150,174);c.font='15px sans-serif';c.fillStyle='#444';c.fillText(['高','中','低','很低'][j],32+j*150,207);for(let x=0;x<125;x++){const v=Math.round(160*(1+co*Math.sin(x*.45)));c.fillStyle=`rgb(${v},${v},${v})`;c.fillRect(32+j*150+x,243,1,68);}}}else{c.fillStyle='white';c.fillRect(320,180,1,1);}return c.getImageData(0,0,640,360).data;}
function pump(){if(busy||!queue.length)return;busy=true;worker.postMessage(queue.shift());}
function render(t){sync();if(scene==='road'&&!loaded){$('status').textContent='正在加载夜景…';return Promise.resolve({loading:true});}const id=++serial;latest[t]=id;$('status').textContent='正在计算…';const p=new Promise((resolve,reject)=>pending.set(id,{resolve,reject,target:t,scene,snapshot:{...configs[t]}}));const kept=[];for(const j of queue){if(j.target===t){pending.get(j.id)?.resolve({superseded:true});pending.delete(j.id);}else kept.push(j);}queue=kept;queue.push({id,target:t,sceneKey:scene,state:{...configs[t],scene:scene==='reading'||example==='near'?'reading':scene==='road'?'road':'star'},input:makeScene(),width:640,height:360});pump();return p;}
function renderBoth(){return Promise.all([render('a'),render('b')]).catch(()=>{});}
function pointImage(data){const image=new ImageData(640,360);for(let y=0;y<360;y++)for(let x=0;x<640;x++){const ux=128+(x-320)/10,uy=128+(y-180)/10,px=Math.floor(ux),py=Math.floor(uy),tx=ux-px,ty=uy-py;let value=0;if(px>=0&&px<255&&py>=0&&py<255)value=data.psf[py*256+px]*(1-tx)*(1-ty)+data.psf[py*256+px+1]*tx*(1-ty)+data.psf[(py+1)*256+px]*(1-tx)*ty+data.psf[(py+1)*256+px+1]*tx*ty;const v=Math.max(0,Math.min(1,(Math.log10(Math.max(value,1e-12))+6)/6)),i=(y*640+x)*4;image.data[i]=Math.round(225*v);image.data[i+1]=Math.round(250*v);image.data[i+2]=Math.round(245*v);image.data[i+3]=255;}return image;}
worker.onmessage=({data:d})=>{busy=false;const p=pending.get(d.id);pending.delete(d.id);if(p){if(d.error){$('status').textContent='模型暂不可用';p.reject(new Error(d.error));}else{const t=p.target;if(latest[t]===d.id){results[t]=d;const img=p.scene==='psf'?pointImage(d):new ImageData(d.output,640,360);$('canvas-'+t).getContext('2d').putImageData(img,0,0);if(edit===t)graphs(d);}p.resolve({scenario:t,settings:p.snapshot,residualCylinder:residualCylinder(p.snapshot)});}}pump();if(!busy&&!queue.length)$('status').textContent='';};worker.onerror=()=>{$('status').textContent='光学模型暂不可用';for(const p of pending.values())p.reject(new Error('Worker error'));pending.clear();queue=[];busy=false;};
function graphs(d){const g=$('psf').getContext('2d'),img=g.createImageData(256,256);for(let i=0;i<d.psf.length;i++){const v=Math.max(0,Math.min(1,(Math.log10(Math.max(d.psf[i],1e-12))+6)/6));img.data[i*4]=225*v;img.data[i*4+1]=250*v;img.data[i*4+2]=245*v;img.data[i*4+3]=255;}g.putImageData(img,0,0);$('psf-note').textContent='中央 '+(d.field*60).toFixed(1)+'角分裁剪；图像卷积核保留 '+(d.retained*100).toFixed(2)+'% 的 PSF 能量。';const m=$('mtf').getContext('2d');m.fillStyle='#0b141c';m.fillRect(0,0,520,280);m.font='12px sans-serif';for(let j=0;j<=4;j++){const y=22+j*50;m.strokeStyle='#293b47';m.beginPath();m.moveTo(48,y);m.lineTo(498,y);m.stroke();m.fillStyle='#b4c2cd';m.textAlign='right';m.fillText((1-j/4).toFixed(2),40,y+4);m.textAlign='center';m.fillText(String(j*10),48+j*112.5,242);}m.fillText('空间频率 · 周期/度',273,268);for(const [a,color,dash]of [[d.ideal,'#708390',[4,4]],[d.horizontal,'#8de3ce',[]],[d.vertical,'#efb88a',[5,3]]]){m.strokeStyle=color;m.lineWidth=2;m.setLineDash(dash);m.beginPath();a.forEach((v,i)=>i?m.lineTo(48+450*i/40,22+200*(1-v)):m.moveTo(48,22+200*(1-v)));m.stroke();}m.setLineDash([]);}
function applyExample(v){example=v;configs={a:{...base,glasses:true},b:{...base,toric:true}};if(v==='aspheric'){configs.a={...base,astig:0,aspheric:false};configs.b={...base,astig:0,aspheric:true};}if(v==='near'){configs.a={...base,astig:0,distance:0};configs.b={...base,astig:0,distance:2.5};scene='reading';}setView('split');renderBoth();}
function guide(){const e=evidence[lens];$('guide-title').textContent=e.title;$('guide-summary').textContent=e.summary;for(const key of ['pros','cons'])$(key).replaceChildren(...e[key].map(([text,source])=>{const li=document.createElement('li');li.append(document.createTextNode(text+' '));const a=document.createElement('a');a.href=sources[source];a.target='_blank';a.rel='noopener';a.textContent='来源 ↗';li.append(a);return li;}));document.querySelectorAll('[data-lens]').forEach(e=>e.setAttribute('aria-pressed',String(e.dataset.lens===lens)));$('guide-note').textContent=lens==='enhanced'?'试验范围：Eyhance、Impress、NSP-3 与 Tecnis monofocal 比较；172 位患者，随访两个月。未发现显著差异不等于证明等效，也不能排除罕见不良事件。':'仅凭晶状体类别无法预测个人效果。本应用尚未经过眼科医生审核。';}
function open(id){$(id).showModal();}for(const d of document.querySelectorAll('dialog')){d.querySelector('[data-close]').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d&&e.clientX<d.getBoundingClientRect().left)d.close();});}
$('guide-open').onclick=()=>{guide();open('guide-dialog');};$('science-open').onclick=()=>{sync();open('science-dialog');};$('settings-open').onclick=()=>open('settings-dialog');$('methods-open').onclick=()=>open('methods-dialog');fetch('method-content.html').then(r=>{if(!r.ok)throw Error();return r.text();}).then(h=>{$('method-content').innerHTML=h;}).catch(()=>{$('method-content').innerHTML='<p>请阅读<a href="VALIDATION.md">核对记录与模型前提</a>.</p>';});$('fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen?.();else document.documentElement.requestFullscreen?.().catch(()=>{});};
for(const key of ['aspheric','toric','glasses'])$(key).onchange=()=>{configs[edit][key]=$(key).checked;render(edit).catch(()=>{});};for(const key of ['astig','rotation','pupil','decenter'])$(key).oninput=()=>{configs[edit][key]=Number($(key).value);sync();clearTimeout(timer);timer=setTimeout(()=>render(edit).catch(()=>{}),100);};$('copy').onclick=()=>{configs[edit]={...configs[edit==='a'?'b':'a']};render(edit).catch(()=>{});};$('reset').onclick=()=>applyExample(example);$('example').onchange=()=>applyExample($('example').value);$('scene').onchange=()=>{scene=$('scene').value;if(example!=='near'){configs.a.distance=configs.b.distance=scene==='reading'?2.5:0;}renderBoth();};$('distance').onchange=()=>{configs.a.distance=configs.b.distance=Number($('distance').value);renderBoth();};document.querySelectorAll('[data-edit]').forEach(e=>e.onclick=()=>{edit=e.dataset.edit;sync();});document.querySelectorAll('[data-view]').forEach(e=>e.onclick=()=>setView(e.dataset.view));document.querySelectorAll('[data-lens]').forEach(e=>e.onclick=()=>{lens=e.dataset.lens;guide();});$('divider').oninput=()=>{$('stage').style.setProperty('--split',$('divider').value+'%');};document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;if(['ArrowLeft','ArrowRight','ArrowDown'].includes(e.key)){e.preventDefault();setView(e.key==='ArrowLeft'?'a':e.key==='ArrowRight'?'b':'split');}});
let step=0,answers=[];const questions=[{q:'您更重视什么？',a:[['contrast','夜间对比清晰'],['freedom','较少依赖眼镜']],note:'整理偏好，方便与医生讨论。'},{q:'习惯戴阅读眼镜吗？',a:[['yes','习惯，可以接受'],['no','希望尽量少戴']],note:'这个偏好有助于权衡晶状体的优缺点。'},{q:'医生确认有角膜散光了吗？',a:[['yes','是'],['no','否'],['unknown','暂时不知道']],note:'Astigmatism 就是散光，需要眼部测量。'}];function decision(){const done=step===3;$('step-label').textContent=done?'准备与医生讨论':'您的偏好 · '+(step+1)+' / 3';$('decision-back').hidden=step===0;if(!done){const q=questions[step];$('decision-question').textContent=q.q;$('decision-note').textContent=q.note;$('decision-options').replaceChildren(...q.a.map(([value,label])=>{const b=document.createElement('button');b.textContent=label;if(value==='unknown')b.className='small-choice';b.onclick=()=>{answers[step]=value;step++;decision();};return b;}));}else{const contrast=answers[0]==='contrast',glasses=answers[1]==='yes';$('decision-question').textContent=contrast&&glasses?'询问以看远为目标的 Monofocal（单焦点）。':contrast?'先讨论对比度，再讨论眼镜依赖。':'讨论少戴眼镜的收益和代价。';$('decision-note').textContent=(contrast&&glasses?'您的偏好适合从此处开始讨论；这不是处方。':contrast?'询问 Enhanced monofocal（增强型单焦点）能增加多少中距离视力。':'询问 EDOF（延长焦深）与 Multifocal（多焦点），包括光晕和暗处对比度。')+(answers[2]==='unknown'?'散光矫正需要她的检查数据。':answers[2]==='yes'?'询问是否值得采用 Toric（散光型）。':'确认是否需要散光矫正。');const b=document.createElement('button');b.textContent='查看取舍';b.onclick=()=>{lens=contrast?(glasses?'mono':'enhanced'):'edof';guide();open('guide-dialog');};const r=document.createElement('button');r.textContent='重新开始';r.className='small-choice';r.onclick=()=>{step=0;answers=[];decision();};$('decision-options').replaceChildren(b,r);}}$('decision-back').onclick=()=>{step=Math.max(0,step-1);answers=answers.slice(0,step);decision();};
function validate(input){if(!input||typeof input!=='object'||Array.isArray(input))throw Error('Expected settings');const allowed=new Set(['target','scene','view','aspheric','toric','glasses','astig','rotation','pupil','decenter']);for(const k of Object.keys(input))if(!allowed.has(k))throw Error('Unknown field: '+k);for(const [k,list]of Object.entries({target:['a','b'],scene:['psf','road','reading'],view:['a','b','split']}))if(k in input&&!list.includes(input[k]))throw Error('Invalid '+k);for(const k of ['aspheric','toric','glasses'])if(k in input&&typeof input[k]!=='boolean')throw Error('Invalid '+k);for(const[k,[min,max]]of Object.entries({astig:[0,2.5],rotation:[0,30],pupil:[2,6],decenter:[0,.6]}))if(k in input&&(typeof input[k]!=='number'||!Number.isFinite(input[k])||input[k]<min||input[k]>max))throw Error('Invalid '+k);return input;}
if(document.modelContext?.registerTool){const ac=new AbortController();window.addEventListener('pagehide',()=>ac.abort(),{once:true});try{Promise.resolve(document.modelContext.registerTool({name:'configure_lens_comparison',description:'Configure one A/B single-focus optical example. Does not model a commercial implant or record medical data.',inputSchema:{type:'object',properties:{target:{type:'string',enum:['a','b']},scene:{type:'string',enum:['psf','road','reading']},view:{type:'string',enum:['a','b','split']},aspheric:{type:'boolean'},toric:{type:'boolean'},glasses:{type:'boolean'},astig:{type:'number',minimum:0,maximum:2.5},rotation:{type:'number',minimum:0,maximum:30},pupil:{type:'number',minimum:2,maximum:6},decenter:{type:'number',minimum:0,maximum:.6}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async raw=>{const i=validate(raw);edit=i.target||edit;if(i.view)setView(i.view);const changedScene=i.scene&&i.scene!==scene;if(i.scene){scene=i.scene;if(example==='near'&&scene!=='reading'){example='cylinder';configs.a.distance=configs.b.distance=0;}}for(const k of ['aspheric','toric','glasses','astig','rotation','pupil','decenter'])if(k in i)configs[edit][k]=i[k];if(changedScene)return await renderBoth();return await render(edit);}},{signal:ac.signal})).catch(()=>{});}catch{}}
